import React, { useState, useEffect } from 'react'
import { Container, Row, Col, Table, Button, Badge } from 'reactstrap'
import { BASE_URL } from '../../utils/config'

const ManageUsers = () => {
   const [users, setUsers] = useState([])
   const [loading, setLoading] = useState(true)
   const [error, setError] = useState(null)

   useEffect(() => {
      const fetchUsers = async () => {
         try {
            const token = localStorage.getItem('token'); // Lấy token đã lưu ở Login

            const res = await fetch(`${BASE_URL}/users`, {
               method: 'GET',
               headers: {
                  // Gửi token đi để "xin phép" vào cổng verifyAdmin
                  'Authorization': `Bearer ${token}` 
               }
            });

            const result = await res.json();

            if (!res.ok) {
               // Nếu Backend trả về 401 hoặc 403, dòng này sẽ hiện lỗi
               setError(result.message || "Bạn không có quyền Admin!");
            } else {
               setUsers(result.data || []);
            }
            setLoading(false);
         } catch (err) {
            setError("Lỗi kết nối Server!");
            setLoading(false);
         }
      };

      fetchUsers();
   }, []);

   // ... Phần render Table và hàm deleteUser giữ nguyên như bản trước
   return (
       <section className="mt-5 pt-5">
           <Container>
               <Row>
                   <Col lg='12'>
                       <h3 className="mb-4 fw-bold">Quản trị người dùng</h3>
                       {loading && <h4>Đang tải...</h4>}
                       {error && <div className="alert alert-danger">{error}</div>}
                       {!loading && !error && (
                           <Table hover borderless className="shadow-sm bg-white rounded">
                               <thead className="bg-light">
                                   <tr>
                                       <th>Tên</th>
                                       <th>Email</th>
                                       <th>Quyền</th>
                                       <th className="text-center">Thao tác</th>
                                   </tr>
                               </thead>
                               <tbody>
                                   {users.map(user => (
                                       <tr key={user._id}>
                                           <td>{user.username}</td>
                                           <td>{user.email}</td>
                                           <td><Badge color="success">{user.role}</Badge></td>
                                           <td className="text-center">
                                               <Button color="danger" size="sm">Xóa</Button>
                                           </td>
                                       </tr>
                                   ))}
                               </tbody>
                           </Table>
                       )}
                   </Col>
               </Row>
           </Container>
       </section>
   );
}

export default ManageUsers
